let dadosPedido = msg.payload;
let nomeString = String(dadosPedido.nome || "").trim();

// Limita a 16 caracteres (8 registradores) e troca o que não cabe em 1 byte por "?"
nomeString = nomeString.slice(0, 16).replace(/[^\u0020-\u00FF]/g, "?");
nomeString = nomeString.padEnd(16, " ");

let modbusRegisters = [];
for (let i = 0; i < nomeString.length; i += 2) {
    let byte1 = nomeString.charCodeAt(i);
    let byte2 = nomeString.charCodeAt(i + 1) || 32;
    modbusRegisters.push((byte1 << 8) | byte2);
}
let msgRegistradores = { payload: modbusRegisters };
let msgTrigger = { payload: dadosPedido.novoPedido, topic: 'Trig' };
return [msgRegistradores, msgTrigger];

let bloco1 = flow.get('bloco1') || [];
let bloco2 = flow.get('bloco2') || [];

if (msg.topic === 'bloco1') {
    bloco1 = msg.payload;
    flow.set('bloco1', bloco1);
} else if (msg.topic === 'bloco2') {
    bloco2 = msg.payload;
    flow.set('bloco2', bloco2);
}

let rawRegisters = bloco1.concat(bloco2);
if (rawRegisters.length < 225) return null;

const MAPA_ESTADOS = {
    1: 'Em espera na fila (Estoque 1 - Bruto)',
    2: 'Torno: Torneando o primeiro lado',
    3: 'Torno: Torneando o segundo lado',
    4: 'Estoque 2 (Torneadas): Aguardando Centro de Usinagem',
    5: 'Centro: Usinando peça',
    6: 'Estoque 3 (Usinadas): Aguardando Centro para customizar a sua peça!',
    7: 'Centro: Customizando sua peça',
    8: 'Peça pronta'
};

let pedidosFormatados = [];
const totalPedidos = Math.floor(rawRegisters.length / 9);

for (let i = 0; i < totalPedidos; i++) {
    let offset = i * 9;
    let estadoCodigo = rawRegisters[offset + 8] & 0xFF;
    if (estadoCodigo === 0) continue;

    let nomeChars = [];
    for (let w = 0; w < 8; w++) {
        let wordVal = rawRegisters[offset + w];
        let charHigh = (wordVal >> 8) & 0xFF;
        let charLow = wordVal & 0xFF;
        if (charHigh !== 0) nomeChars.push(String.fromCharCode(charHigh));
        if (charLow !== 0) nomeChars.push(String.fromCharCode(charLow));
    }
    let nomeString = nomeChars.join("").trim();
    if (nomeString.length > 0) {
        pedidosFormatados.push({
            id: 'ordem_' + (i + 1) + '_' + nomeString,
            nome: nomeString,
            tipo: nomeString === 'SENAI' ? 'PADRAO' : 'PERSONALIZADO',
            estado: MAPA_ESTADOS[estadoCodigo] || 'Em processamento'
        });
    }
}
return { payload: pedidosFormatados };

// Passagem direta: a função "Processamento" (Leitura geral)
// já entrega {estacao, operando} pronto para o sinótico.
return msg;

if (!Array.isArray(msg.payload) || msg.payload.length < 3) return null;

// Registrador vem sem sinal (0..65535): converte para número com sinal (-32768..32767)
const s16 = v => (v > 32767 ? v - 65536 : v);
const [e1, e2, e3] = msg.payload.map(s16);

// Guarda o último estoque lido do CLP (usado na escrita, para não zerar os outros)
flow.set('estoque', [e1, e2, e3]);

return { payload: { estacao: "estoque", estoque1: e1, estoque2: e2, estoque3: e3 } };

const INTERVALO_MAXIMO = 6000;
let timer = context.get('timer') || null;

function dispararTimeout() {
    context.set('timer', null);
    node.status({ fill: "red", shape: "ring", text: "Timeout: Sem comunicação" });
    node.send({ payload: { "cicloAutomatico": false } });
}

if (timer) clearTimeout(timer);

if (Array.isArray(msg.payload) && msg.payload[0] === true) {
    timer = setTimeout(dispararTimeout, INTERVALO_MAXIMO);
    context.set('timer', timer);
    node.status({ fill: "green", shape: "dot", text: "Conectado" });
    return { payload: { "cicloAutomatico": true } };
} else {
    context.set('timer', null);
    node.status({ fill: "red", shape: "dot", text: "Resposta inesperada" });
    return { payload: { "cicloAutomatico": false } };
}

const INTERVALO_MAXIMO = 6000;

let timer = context.get('timer');

function desconectado() {
    context.set('timer', null);

    node.status({
        fill: "red",
        shape: "ring",
        text: "CLP desconectado"
    });

    return {
        payload: {
            clpConectado: false
        }
    };
}

if (timer) {
    clearTimeout(timer);
}

// Se o Processamento principal recebeu corretamente
// o pacote de 9 coils, o CLP respondeu ao Modbus.
if (Array.isArray(msg.payload) && msg.payload.length >= 1) {

    timer = setTimeout(() => {
        node.send(desconectado());
    }, INTERVALO_MAXIMO);

    context.set('timer', timer);

    node.status({
        fill: "green",
        shape: "dot",
        text: "CLP conectado"
    });

    return {
        payload: {
            clpConectado: true,
            clpLigado: Boolean(msg.payload[0])
        }
    };
}

return desconectado();

finalize:
// Campo "Na saída" (On Close)
let timer = context.get('timer');
if (timer) {
    clearTimeout(timer);
    context.set('timer', null);
}

