// Indicador de status da Rotina Automática (vem do switch do dashboard)
if (msg.payload === true) {
    node.status({ fill: "green", shape: "dot", text: "Rotina automática LIGADA" });
} else {
    node.status({ fill: "red", shape: "dot", text: "Rotina automática DESLIGADA" });
}
return null;

// Recebe os 9 coils (199 a 207) e distribui para 4 saídas
const coils = msg.payload;
if (!Array.isArray(coils) || coils.length < 9) return null;

// índices: 0=199 | 1=200 | 5=204 (Rotina automática) | 6=205 (CLP ON) | 7=206 | 8=207
const tornoOperando  = Boolean(coils[0] || coils[1]);
const centroOperando = Boolean(coils[7] || coils[8]);

return [
    { payload: [Boolean(coils[6])] },                                // saída 1 -> watchdog "CLP conectado"
    { payload: { estacao: 'torno',  operando: tornoOperando } },     // saída 2 -> Torno
    { payload: { estacao: 'centro', operando: centroOperando } },    // saída 3 -> Centro
    { payload: [Boolean(coils[5])] }                                 // saída 4 -> watchdog "Rotina automática"
];

// Recupera o último valor salvo no contexto do nó
let ultimoValor = context.get('ultimoValor');

// Verifica se o valor atual mudou em relação ao anterior
if (msg.payload !== ultimoValor) {
    // Atualiza o contexto com o novo valor
    context.set('ultimoValor', msg.payload);

    // Retorna a mensagem para continuar o fluxo
    return {
        topic: 'Auto',
        payload: msg.payload
    };
}

// Se for igual, retorna null (bloqueia o envio)
return null;

// Usa como base o último estoque LIDO do CLP, para não zerar os outros dois valores
const atual = flow.get('estoque');
if (!Array.isArray(atual)) {
    node.warn('Estoque ainda não foi lido do CLP. Escrita cancelada para não zerar os outros valores.');
    return null;
}
let [e1, e2, e3] = atual;
const valor = Number(msg.payload) || 0;

if (msg.topic === 'E1') e1 = valor;
else if (msg.topic === 'E2') e2 = valor;
else if (msg.topic === 'E3') e3 = valor;

// & 0xFFFF converte negativos (ex.: -2) para o formato de registrador de 16 bits
return { payload: [e1, e2, e3].map(x => x & 0xFFFF) };

// Recupera o último estado de Auto
let autoRot = context.get('Auto') ?? false;

// Converte a entrada atual para booleano
let dadoAtualizado = Boolean(msg.payload);

// Trig é momentâneo e NÃO é armazenado
let trig = false;

// Atualiza somente a variável correspondente ao tópico
if (msg.topic === 'Trig') {

    trig = dadoAtualizado;

} else if (msg.topic === 'Auto') {

    autoRot = dadoAtualizado;
    context.set('Auto', autoRot);
}

// Saída para Force Multiple Coils
// Índice 0 = Trig
// Índice 1 = Auto
msg.payload = [trig, autoRot];

return msg;

