// =====================================================================
// AGREGADOR DE PRODUTIVIDADE FMS - tudo calculado a partir do CLP
// =====================================================================
// >>> ÚNICO LUGAR COM VALORES CONFIGURÁVEIS <<<
const CFG = {
    META_TURNO: 40,            // peças planejadas para o turno/evento
    DURACAO_TURNO_H: 16,       // janela do gráfico/turno em horas (07:00 até 23:00 = 16 h)
    INICIO_TURNO_HORA: 7,      // hora de início (zera os contadores todo dia) | null = começa ao implantar/resetar
    PASSO_GRAFICO_H: 2,        // intervalo entre os pontos do gráfico de ritmo (em horas)
    ESTOQUE_MINIMO: 2,         // Estoque 1 abaixo disso (e sem operar) = "Estoque Baixo"
    N_MEDIA: 10,               // nº de amostras da média móvel
    SALVAR_A_CADA_S: 30,       // gravação periódica em disco (além das gravações por evento: peça concluída, troca de etapa, reset)
    PERMITIR_SIMULACAO: false, // true = botões do Injetor simulam de novo (somente para testes)
    ESTAGIOS: [
        { id: 'torno_l1',     nome: '1. Torno: Faceamento & L1',          teorico: 90 },
        { id: 'torno_l2',     nome: '2. Torno: Perfil & L2',              teorico: 85 },
        { id: 'centro_usina', nome: '3. Centro: Furação & Contorno',      teorico: 120 },
        { id: 'centro_grava', nome: '4. Centro: Gravação do Nome',        teorico: 80 },
        { id: 'logistica',    nome: '5. Logística: Manipulador & Rampas', teorico: 70 }
    ],
    // % de conclusão da peça: faixa (min->max) de cada estado do CLP. A duração vem do tempo REAL medido
    // no estágio (média móvel) ou, sem amostras, do teórico; estados de espera usam durPadrao (s).
    ETAPAS: [
        { chave: 'primeiro lado', min: 10, max: 30, estagio: 0 },
        { chave: 'segundo lado',  min: 30, max: 45, estagio: 1 },
        { chave: 'estoque 2',     min: 45, max: 60, durPadrao: 15 },
        { chave: 'usinando',      min: 60, max: 75, estagio: 2 },
        { chave: 'estoque 3',     min: 75, max: 85, durPadrao: 5 },
        { chave: 'customizando',  min: 85, max: 98, estagio: 3 },
        { chave: 'pronta',        min: 98, max: 100, durPadrao: 1 },
        { chave: 'espera',        min: 0,  max: 10, durPadrao: 5 }
    ],
    ESTADOS: [
        { estado: 'PRODUZINDO',    label: 'Peça em Processamento / Linha Ativa',  cor: '#10b981', cod: 1, curto: 'Ativa' },
        { estado: 'OCIOSO',        label: 'CLP Parado (Sem Pedidos)',             cor: '#64748b', cod: 2, curto: 'Ociosa' },
        { estado: 'ESTOQUE_BAIXO', label: 'Estoque Baixo (Requisitar Recarga)',   cor: '#f59e0b', cod: 3, curto: 'Est. baixo' },
        { estado: 'EMERGENCIA',    label: 'Emergência Acionada',                  cor: '#ef4444', cod: 4, curto: 'Emergência' },
        { estado: 'FALHA_ROBO',    label: 'Falha Comunicação Robô',               cor: '#a855f7', cod: 5, curto: 'Falha robô' }
    ]
};
// FUSO HORÁRIO FIXO (Brasília = UTC-3, sem horário de verão). Independe da configuração de fuso do Windows.
const FUSO_H = -3;
const FUSO_MS = FUSO_H * 3600000;
const loc = ts => new Date(ts + FUSO_MS);          // use sempre getUTC*() no resultado
const TZ_OPT = { timeZone: 'America/Sao_Paulo' };
const CICLO_IDEAL = CFG.ESTAGIOS.reduce((s, e) => s + e.teorico, 0); // soma dos estágios (445 s)
const CHAVE = 'fms_prod_v2';
const SIG = CFG.INICIO_TURNO_HORA + '|' + CFG.DURACAO_TURNO_H + '|' + CFG.PASSO_GRAFICO_H; // muda se a janela for alterada

const agora = Date.now();
// ---- aguarda a restauração do arquivo ao iniciar (no máximo 10 s)
if (flow.get('fms_carregado') === false && agora - (flow.get('fms_carga_t0') || 0) < 10000) return null;
let salvarAgora = false;   // true = grava o arquivo nesta passagem
let arquivar = null;       // != null = guarda no histórico o período que está sendo encerrado
const r1 = x => Math.round(x * 10) / 10;
const media = a => a.length ? a.reduce((s, v) => s + v, 0) / a.length : null;
const ehPronta = t => String(t || '').toLowerCase().includes('pronta');
const ehPadrao = n => !n || String(n).trim().toUpperCase() === 'SENAI';
function hojeStr(ts) { const d = loc(ts); return d.getUTCFullYear() + '-' + (d.getUTCMonth() + 1) + '-' + d.getUTCDate(); }
function inicioDoTurno(ts) {
    if (CFG.INICIO_TURNO_HORA === null) return ts;
    const inicioDia = Math.floor((ts + FUSO_MS) / 86400000) * 86400000 - FUSO_MS;   // 00:00 de Brasília
    return inicioDia + CFG.INICIO_TURNO_HORA * 3600000;
}
function estagioDoEstado(txt) {
    const s = String(txt || '').toLowerCase();
    if (s.includes('primeiro lado')) return 0;
    if (s.includes('segundo lado')) return 1;
    if (s.includes('usinando')) return 2;
    if (s.includes('customizando')) return 3;
    if (s.includes('estoque 2') || s.includes('estoque 3')) return 4;
    return -1; // espera na fila / peça pronta: não entra nos gargalos
}
function etapaDoEstado(txt) {
    const s = String(txt || '').toLowerCase();
    return CFG.ETAPAS.find(x => s.includes(x.chave)) || { chave: '?', min: 0, max: 100, durPadrao: 100 };
}
function durEtapa(et) {   // duração de referência (s) da etapa: medida > teórica > padrão
    if (et.estagio !== undefined) {
        const m = media(h.amostrasEstagio[et.estagio] || []);
        return (m !== null && m > 1) ? m : CFG.ESTAGIOS[et.estagio].teorico;
    }
    return et.durPadrao;
}
function novoHistorico(prev) {
    return {
        dia: hojeStr(agora),
        sig: SIG,
        turnoInicio: inicioDoTurno(agora),
        totalEntregue: 0, pecasPadrao: 0, pecasPersonalizadas: 0, baseEntregues: 0,
        ultimaPecaConcluida: '—',
        segEstado: { PRODUZINDO: 0, OCIOSO: 0, ESTOQUE_BAIXO: 0, EMERGENCIA: 0, FALHA_ROBO: 0 },
        horas: {}, conclusoes: [], opSegUltimaConclusao: 0,
        amostrasCiclo: [], amostrasEstagio: CFG.ESTAGIOS.map(() => []),
        prontasVistas: prev ? prev.prontasVistas : null,   // null = ainda não leu a fila
        pedidosVistos: prev ? prev.pedidosVistos : {},
        tel: prev ? prev.tel : { clpConectado: false, clpLigado: null, cicloAutomatico: false,
                                 tornoOp: false, centroOp: false, estoque1: null,
                                 emergencia: false, falhaRobo: false, filaPendente: 0 },
        estadoAtual: 'OCIOSO', estadoForcado: null, ultimoTick: null
    };
}

let h = flow.get(CHAVE);
if (!h) h = novoHistorico(null);
if (h.sig !== SIG || (CFG.INICIO_TURNO_HORA !== null && h.dia !== hojeStr(agora))) { arquivar = { motivo: (h.sig !== SIG ? 'janela_alterada' : 'virou_dia'), h: h }; h = novoHistorico(h); salvarAgora = true; } // janela alterada ou virou o dia

// MIGRAÇÃO: se o início do turno salvo não bate com o 07:00 de Brasília (ex.: foi salvo com o fuso errado),
// realinha a janela e desloca os blocos de horas, sem perder peças contadas nem o histórico.
if (CFG.INICIO_TURNO_HORA !== null) {
    const esperado = inicioDoTurno(agora);
    if (h.turnoInicio !== esperado) {
        const delta = Math.round((esperado - h.turnoInicio) / 3600000);
        const novas = {};
        Object.keys(h.horas).forEach(k => {
            const j = Number(k) - delta;
            if (j >= 0 && j < CFG.DURACAO_TURNO_H) novas[j] = h.horas[k];
        });
        h.horas = novas;
        h.turnoInicio = esperado;
        salvarAgora = true;
    }
}

let notificacao = null;
const p = msg.payload;

// ---- registra uma peça concluída
function registrarConclusao(nome, amostraSeg) {
    h.totalEntregue += 1;
    if (ehPadrao(nome)) h.pecasPadrao += 1; else h.pecasPersonalizadas += 1;
    h.ultimaPecaConcluida = nome;
    h.conclusoes.push(agora);
    if (h.conclusoes.length > 500) h.conclusoes.shift();
    if (amostraSeg > 0) {
        h.amostrasCiclo.push(amostraSeg);
        while (h.amostrasCiclo.length > CFG.N_MEDIA) h.amostrasCiclo.shift();
    }
    notificacao = { nome: nome, timestamp: new Date(agora).toLocaleTimeString('pt-BR', TZ_OPT) };
}

// ---- 0. TEMPO: o intervalo desde a última mensagem vai para o estado anterior
if (h.ultimoTick !== null && h.tel.clpConectado) {
    const dt = Math.min(5, (agora - h.ultimoTick) / 1000);
    if (dt > 0) {
        h.segEstado[h.estadoAtual] += dt;
        const idx = Math.floor((agora - h.turnoInicio) / 3600000);
        if (idx >= 0 && idx < CFG.DURACAO_TURNO_H) {
            const b = h.horas[idx] || (h.horas[idx] = { ativo: 0, parado: 0 });
            if (h.estadoAtual === 'PRODUZINDO') b.ativo += dt; else b.parado += dt;
        }
    }
}
h.ultimoTick = agora;

// ---- 1. INJETOR (reset sempre funciona; simulação só se PERMITIR_SIMULACAO)
if (msg.topic === 'fms/injetar_estado') {
    const cmd = p || {};
    if (cmd.tipo === 'reset_metricas') {
        arquivar = arquivar || { motivo: 'reset_manual', h: h };
        h = novoHistorico(h);
        h.ultimoTick = agora;
        salvarAgora = true;
    } else if (CFG.PERMITIR_SIMULACAO) {
        if (cmd.tipo === 'set_estado') h.estadoForcado = cmd.estado;
        if (cmd.tipo === 'simular_conclusao') registrarConclusao(cmd.nome || 'SENAI', 0);
    }
}

// ---- 2. FILA DE PEDIDOS VINDA DO CLP (array)
if (Array.isArray(p)) {
    const primeira = (h.prontasVistas === null);
    const prontas = p.filter(o => ehPronta(o.estado));
    const ids = prontas.map(o => o.id);

    if (primeira) {
        // 1ª leitura: peças já prontas na fila contam como entregues (sem estatística de tempo)
        prontas.forEach(o => {
            h.totalEntregue += 1; h.baseEntregues += 1;
            if (ehPadrao(o.nome)) h.pecasPadrao += 1; else h.pecasPersonalizadas += 1;
        });
        if (prontas.length) h.ultimaPecaConcluida = prontas[prontas.length - 1].nome || 'SENAI';
    } else {
        const novos = prontas.filter(o => !h.prontasVistas.includes(o.id));
        if (novos.length) {
            const opSeg = h.segEstado.PRODUZINDO;
            const amostra = (opSeg - h.opSegUltimaConclusao) / novos.length;
            novos.forEach(o => registrarConclusao(o.nome || 'SENAI', amostra));
            h.opSegUltimaConclusao = opSeg;
        }
    }
    h.prontasVistas = ids;
    h.tel.filaPendente = p.filter(o => !ehPronta(o.estado)).length;

    // tempo real gasto em cada estágio (gargalos) + dados persistidos de cada pedido (nome, ordem, criação, início da etapa)
    const vistos = {};
    let mudouFila = Object.keys(h.pedidosVistos).length !== p.length;
    p.forEach((o, ord) => {
        const est = estagioDoEstado(o.estado);
        const ant = h.pedidosVistos[o.id];
        const base = { nome: o.nome, tipo: o.tipo, ord: ord };
        if (!ant) {
            vistos[o.id] = Object.assign(base, { estado: o.estado, estagio: est, desde: agora, parcial: primeira, criado: agora });
            mudouFila = true;
        } else if (ant.estado !== o.estado) {
            if (!ant.parcial && ant.estagio >= 0) {
                const arr = h.amostrasEstagio[ant.estagio];
                arr.push((agora - ant.desde) / 1000);
                while (arr.length > CFG.N_MEDIA) arr.shift();
            }
            vistos[o.id] = Object.assign(base, { estado: o.estado, estagio: est, desde: agora, parcial: false, criado: ant.criado || agora });
            mudouFila = true;
        } else {
            vistos[o.id] = Object.assign({}, ant, base, { criado: ant.criado || agora });
        }
    });
    h.pedidosVistos = vistos;
    if (mudouFila) salvarAgora = true;   // troca de etapa / pedido novo: grava já (o % da peça não se perde)
}

// ---- 3. TELEMETRIA DO CLP (objetos)
if (p && typeof p === 'object' && !Array.isArray(p)) {
    const t = h.tel;
    if (p.clpConectado !== undefined) {
        t.clpConectado = !!p.clpConectado;
        if (!t.clpConectado) {   // sem comunicação: não mantém estados antigos como se fossem atuais
            t.tornoOp = false; t.centroOp = false; t.cicloAutomatico = false; t.clpLigado = null;
        }
    }
    if (p.clpLigado !== undefined) t.clpLigado = !!p.clpLigado;
    if (p.cicloAutomatico !== undefined) t.cicloAutomatico = !!p.cicloAutomatico;
    if (p.estacao === 'torno') t.tornoOp = !!p.operando;
    if (p.estacao === 'centro') t.centroOp = !!p.operando;
    if (p.estacao === 'estoque' && p.estoque1 !== undefined) t.estoque1 = Number(p.estoque1);
    // sinais opcionais: só passam a valer quando algum nó enviar {emergencia:true} / {falhaRobo:true}
    if (p.emergencia !== undefined) t.emergencia = !!p.emergencia;
    if (p.falhaRobo !== undefined) t.falhaRobo = !!p.falhaRobo;
}

// ---- 4. ESTADO OPERACIONAL ATUAL
(function () {
    const t = h.tel;
    const operando = t.tornoOp || t.centroOp;
    let e;
    if (CFG.PERMITIR_SIMULACAO && h.estadoForcado) e = h.estadoForcado;
    else if (t.emergencia) e = 'EMERGENCIA';
    else if (t.falhaRobo) e = 'FALHA_ROBO';
    else if (!operando && t.estoque1 !== null && t.estoque1 < CFG.ESTOQUE_MINIMO) e = 'ESTOQUE_BAIXO';
    else if (operando || (t.filaPendente > 0 && t.cicloAutomatico && t.clpLigado !== false)) e = 'PRODUZINDO';
    else e = 'OCIOSO';
    h.estadoAtual = e;
})();

// ---- 5. INDICADORES
const seg = h.segEstado;
const totalSeg = Object.values(seg).reduce((s, v) => s + v, 0);
const estados = CFG.ESTADOS.map(e => ({
    estado: e.estado, label: e.label, curto: e.curto, cor: e.cor, cod: e.cod,
    min: r1(seg[e.estado] / 60),
    pct: totalSeg > 0 ? r1(seg[e.estado] / totalSeg * 100) : (e.estado === h.estadoAtual ? 100 : 0)
}));
const disponibilidade = totalSeg > 0
    ? r1((seg.PRODUZINDO + seg.OCIOSO) / totalSeg * 100)
    : ((h.estadoAtual === 'PRODUZINDO' || h.estadoAtual === 'OCIOSO') ? 100 : 0);

const minTotais = CFG.DURACAO_TURNO_H * 60;
const decorrido = Math.max(0, Math.min(minTotais, (agora - h.turnoInicio) / 60000));
const metaAgora = Math.round(CFG.META_TURNO * decorrido / minTotais);
const ritmoAtual = decorrido >= 1 ? (h.totalEntregue / (decorrido / 60)).toFixed(1) : '0.0';
const projecao = decorrido >= 5 ? Math.round(h.totalEntregue / decorrido * minTotais) : null;

const ciclo = media(h.amostrasCiclo);
const eficiencia = ciclo ? r1(Math.min(100, CICLO_IDEAL / ciclo * 100)) : null;

let constancia = null, constanciaLabel = 'Aguardando dados';
if (h.amostrasCiclo.length >= 3) {
    const m = media(h.amostrasCiclo);
    const dp = Math.sqrt(media(h.amostrasCiclo.map(v => (v - m) * (v - m))));
    constancia = r1(Math.max(0, 100 - (dp / m) * 100));
    constanciaLabel = constancia >= 85 ? 'Estável' : (constancia >= 70 ? 'Oscilando' : 'Instável');
}

const estagios = CFG.ESTAGIOS.map((e, i) => {
    const real = media(h.amostrasEstagio[i]);
    return {
        id: e.id, nome: e.nome, teorico: e.teorico,
        real: real === null ? e.teorico : Math.round(real),
        desvio: real === null ? 0 : r1((real - e.teorico) / e.teorico * 100),
        amostras: h.amostrasEstagio[i].length
    };
});

const fmtHora = ts => { const d = loc(ts); return String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); };
const throughput = [];
const passo = CFG.PASSO_GRAFICO_H;
const DUR = CFG.DURACAO_TURNO_H;
const nPontos = Math.ceil(DUR / passo);
const hAgora = (agora - h.turnoInicio) / 3600000;              // horas decorridas desde o início da janela
const realAte = t => h.baseEntregues + h.conclusoes.filter(c => c <= t).length;
function somaHoras(hIni, hFim) {                                // tempo ativo/parado (s) entre duas horas da janela
    let ativo = 0, parado = 0;
    for (let k = Math.floor(hIni); k < hFim; k++) {
        const b = h.horas[k];
        if (b) { ativo += b.ativo; parado += b.parado; }
    }
    return { ativo: ativo, parado: parado };
}
let ultimaGrade = 0;                                            // última marcação da grade já alcançada (h)
for (let i = 0; i <= nPontos; i++) {
    const hFim = Math.min(DUR, i * passo);
    const ts = h.turnoInicio + hFim * 3600000;
    const passado = hFim <= hAgora;
    const pt = {
        hora: fmtHora(ts),
        frac: hFim / DUR,                                       // posição horizontal (0 a 1) na janela
        meta: Math.round(CFG.META_TURNO * hFim / DUR),
        real: realAte(Math.min(ts, agora)),
        entreguesHora: 0, tempoAtivo: '0m', tempoParado: '0m',
        futuro: !passado, atual: false
    };
    if (passado) ultimaGrade = hFim;
    if (i > 0 && passado) {
        const hIni = Math.min(DUR, (i - 1) * passo);
        const ini = h.turnoInicio + hIni * 3600000;
        pt.entreguesHora = h.conclusoes.filter(c => c > ini && c <= ts).length;
        const s = somaHoras(hIni, hFim);
        pt.tempoAtivo = Math.round(s.ativo / 60) + 'm';
        pt.tempoParado = Math.round(s.parado / 60) + 'm';
    }
    throughput.push(pt);
}
// ponto "EM ANDAMENTO": fica na hora exata de agora e anda junto com o relógio
if (hAgora >= 0 && hAgora < DUR) {
    const ini = h.turnoInicio + ultimaGrade * 3600000;
    const s = somaHoras(ultimaGrade, hAgora + 1 / 3600);        // inclui a hora corrente
    throughput.push({
        hora: fmtHora(agora),
        frac: hAgora / DUR,
        meta: r1(CFG.META_TURNO * hAgora / DUR),
        real: realAte(agora),
        entreguesHora: h.conclusoes.filter(c => c > ini && c <= agora).length,
        tempoAtivo: Math.round(s.ativo / 60) + 'm',
        tempoParado: Math.round(s.parado / 60) + 'm',
        futuro: false, atual: true
    });
    throughput.sort((a, b) => a.frac - b.frac);
}


// ---- PRODUÇÃO POR HORA (gráfico de colunas "Peças por Hora"): peças concluídas em cada hora cheia da janela
let producaoHoraria = [];
{
    const horasVisiveis = Math.min(DUR, Math.floor(Math.max(0, hAgora)) + 1);   // da 1ª hora da janela até a hora corrente
    for (let k = 0; k < horasVisiveis; k++) {
        const ini = h.turnoInicio + k * 3600000;
        const fim = ini + 3600000;
        const b = h.horas[k] || { ativo: 0, parado: 0 };
        producaoHoraria.push({
            hora: fmtHora(ini),                                                  // ex.: "09:00" = peças concluídas entre 09:00 e 09:59
            pecas: h.conclusoes.filter(c => c >= ini && c < fim).length,
            minAtivo: Math.round(b.ativo / 60),                                  // minutos em operação ativa nessa hora
            minParado: Math.round(b.parado / 60),
            atual: hAgora >= k && hAgora < k + 1                                 // hora em andamento (parcial)
        });
    }
    // remove as horas vazias do início (antes do evento começar), mantendo sempre a hora corrente
    let primeira = producaoHoraria.findIndex(x => x.pecas > 0 || x.minAtivo > 0 || x.minParado > 0);
    if (primeira < 0) primeira = Math.max(0, producaoHoraria.length - 1);
    producaoHoraria = producaoHoraria.slice(primeira);
}

// ---- SNAPSHOT DA FILA: % de conclusão de cada peça calculado AQUI (fonte única). O navegador não guarda nada:
//      só interpola entre mensagens usando etapaDecorridoS, então F5 / outra tela / outro PC mostram o mesmo valor.
const pedidosSnapshot = Object.keys(h.pedidosVistos)
    .map(id => ({ id: id, v: h.pedidosVistos[id] }))
    .filter(x => x.v.nome !== undefined)
    .sort((a, b) => a.v.ord - b.v.ord)
    .map(x => {
        const v = x.v, et = etapaDoEstado(v.estado);
        const dur = Math.max(1, durEtapa(et));
        const dec = Math.max(0, (agora - v.desde) / 1000);
        return {
            id: x.id, nome: v.nome, tipo: v.tipo, estado: v.estado,
            criadoEm: v.criado || v.desde,
            etapaMin: et.min, etapaMax: et.max, etapaDurS: r1(dur), etapaDecorridoS: r1(dec),
            progressoAtual: r1(et.min + (et.max - et.min) * Math.min(1, dec / dur))
        };
    });

flow.set(CHAVE, h);

// ---- PERSISTÊNCIA: 2ª saída grava o estado em arquivo (alternando A/B para não corromper se faltar energia)
let saida2 = null;
const pasta = flow.get('fms_pasta');
if (notificacao) salvarAgora = true;
if (pasta && (salvarAgora || agora - (context.get('ultimoSave') || 0) >= CFG.SALVAR_A_CADA_S * 1000)) {
    const n = context.get('nSave') || 0;
    context.set('nSave', n + 1);
    context.set('ultimoSave', agora);
    saida2 = {
        topic: 'fms/salvar',
        filename: pasta + '/estado_' + (n % 2 === 0 ? 'a' : 'b') + '.json',
        payload: JSON.stringify({ salvoEm: agora, h: h })
    };
}

// ---- HISTÓRICO: ao zerar (virada de dia / reset), o período encerrado é acrescentado em historico_dashboard.jsonl
let saida3 = null;
if (arquivar && pasta) {
    const a = arquivar.h;
    const temDados = a.totalEntregue > 0 || Object.values(a.segEstado).some(v => v > 0);
    if (temDados) {
        saida3 = {
            topic: 'fms/historico',
            filename: pasta + '/historico_dashboard.jsonl',
            payload: JSON.stringify({ encerradoEm: agora, encerradoEmTexto: new Date(agora).toLocaleString('pt-BR', TZ_OPT), motivo: arquivar.motivo, h: a })
        };
    }
}

return [{
    topic: 'fms/produtividade',
    payload: {
        totalEntregue: h.totalEntregue,
        metaTurno: CFG.META_TURNO,
        pecasPadrao: h.pecasPadrao,
        pecasPersonalizadas: h.pecasPersonalizadas,
        ultimaPecaConcluida: h.ultimaPecaConcluida,
        mediaCicloSegundos: ciclo === null ? null : Math.round(ciclo),
        cicloIdealSegundos: CICLO_IDEAL,
        disponibilidadePercent: disponibilidade,
        eficienciaPercent: eficiencia,
        minutosOperando: r1(seg.PRODUZINDO / 60),
        minutosTotais: minTotais,
        ritmoAtual: ritmoAtual,
        ritmoPlanejado: r1(CFG.META_TURNO / CFG.DURACAO_TURNO_H),
        saldoMeta: h.totalEntregue - metaAgora,
        projecaoPecas: projecao,
        constancia: constancia,
        constanciaLabel: constanciaLabel,
        currentState: h.estadoAtual,
        clpConectado: h.tel.clpConectado,
        cicloAutomatico: h.tel.cicloAutomatico,
        throughput: throughput,
        producaoHoraria: producaoHoraria,
        estagios: estagios,
        estados: estados,
        pedidosSnapshot: pedidosSnapshot
    },
    notificacaoPecaPronta: notificacao
}, saida2, saida3];

