func:
// Roda uma vez ao iniciar/implantar: define a pasta e dispara a leitura dos 2 arquivos (A e B)
const base = String(env.get('USERPROFILE') || env.get('HOME') || '.').replace(/\\/g, '/');
const PASTA = base + '/.node-red/fms_dados';   // <<< PASTA DOS DADOS (altere aqui se quiser outra; a pasta é criada sozinha)
flow.set('fms_pasta', PASTA);
flow.set('fms_carregado', false);              // trava o agregador até terminar a leitura
flow.set('fms_carga_t0', Date.now());
flow.set('fms_leituras', []);
node.status({ fill: 'blue', shape: 'dot', text: 'lendo arquivos...' });
return [[
    { filename: PASTA + '/estado_a.json', slot: 'a' },
    { filename: PASTA + '/estado_b.json', slot: 'b' }
]];

// Recebe a leitura de A e de B (ou o erro se o arquivo não existir) e restaura o mais recente e válido
const lei = flow.get('fms_leituras') || [];
lei.push({ slot: msg.slot, txt: (msg.error || typeof msg.payload !== 'string') ? null : msg.payload });
flow.set('fms_leituras', lei);
if (lei.length < 2) return null;               // espera as duas leituras

let melhor = null;
lei.forEach(l => {
    if (!l.txt) return;
    try {
        const o = JSON.parse(l.txt);
        if (o && o.h && typeof o.salvoEm === 'number' && (!melhor || o.salvoEm > melhor.salvoEm)) melhor = o;
    } catch (e) { /* arquivo incompleto/corrompido: ignora */ }
});
flow.set('fms_leituras', []);

if (melhor) {
    const h = melhor.h;
    Object.keys(h.pedidosVistos || {}).forEach(id => { h.pedidosVistos[id].parcial = true; });   // tempo com o PC desligado não vira "tempo de estágio"
    h.ultimoTick = null;                       // não conta como "tempo de operação" o período em que o PC ficou desligado
    if (h.tel) h.tel.clpConectado = false;     // o estado real do CLP volta com a próxima leitura Modbus
    flow.set('fms_prod_v2', h);
    node.status({ fill: 'green', shape: 'dot', text: 'restaurado: ' + new Date(melhor.salvoEm).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) });
} else {
    node.status({ fill: 'yellow', shape: 'ring', text: 'sem arquivo válido: começando do zero' });
}
flow.set('fms_carregado', true);
return { topic: 'fms/tick', payload: Date.now() };   // atualiza o painel na hora
